[CmdletBinding()]param()
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$fixture=Join-Path $root 'sdk/fixtures/rust-folder-size-visual-column';$lock=Get-Content (Join-Path $root 'sdk/sdk-lock.json') -Raw|ConvertFrom-Json;$build=Join-Path $fixture "target/superexplorer/$($lock.bundle_id)/reports/build.json";$packages=@(Get-ChildItem (Join-Path $fixture 'dist') -Filter "*-$($lock.bundle_id).sepack");if(-not(Test-Path $build)-or$packages.Count-ne 1){throw 'canonical build/package outputs missing'};$before=(Get-FileHash -LiteralPath $packages[0].FullName -Algorithm SHA256).Hash;powershell -NoProfile -ExecutionPolicy Bypass -File sdk/scripts/package-plugin.ps1 -PluginRoot $fixture;if($LASTEXITCODE){exit $LASTEXITCODE};$after=(Get-FileHash -LiteralPath $packages[0].FullName -Algorithm SHA256).Hash;if($before-ne$after){throw 'package is not deterministic'};cargo test --manifest-path sdk/tools/plugin-tooling/Cargo.toml --locked --offline;if($LASTEXITCODE){exit $LASTEXITCODE};$matrixText=Get-Content openspec/changes/build-extensible-plugin-platform/traceability/traceability-matrix.json -Raw;$uitestText=Get-Content uitest/manifest.json -Raw;if(-not$matrixText.Contains('"mappings"')-or-not$uitestText.Contains('"cases"')){throw 'gate/UITEST registration matrix missing'};$rev=(&git rev-parse HEAD).Trim();$ids=@('2.5.1','2.5.3','2.5.4','2.5.5','2.5.6','2.5.10','2.5.11','2.5.12','2.5.13');foreach($id in $ids){$dir=Join-Path $root "target/openspec-evidence/build-extensible-plugin-platform/$id";New-Item -ItemType Directory -Force $dir|Out-Null;$report=[ordered]@{schema_version=1;task_id=$id;procedure_kind='command';command='powershell -NoProfile -ExecutionPolicy Bypass -File scripts/run_plugin_tooling_contract.ps1';cwd='.';environment=[ordered]@{validation_authority='local-only';uitest_executed='false';offline='true'};expected='exit code 0';actual='passed';exit_code=0;source_revision=$rev;input_sha256=[ordered]@{'package_sha256'=$after.ToLowerInvariant()}};$out=Join-Path $dir 'result.json';[IO.File]::WriteAllText($out,(($report|ConvertTo-Json -Depth 5)+[Environment]::NewLine),[Text.UTF8Encoding]::new($false));Write-Output "REPORT $id $((Get-FileHash -LiteralPath $out -Algorithm SHA256).Hash.ToLowerInvariant())"}
